/**
 * Test Case: Login (Data Driven)
 *
 * Tags: @master @datadriven @web
 *
 * Steps (one independent test per row of testdata/opencart_logindata.json):
 * 1) Navigate to My Account -> Login
 * 2) Enter the row's email and password (blank/whitespace values are left empty)
 * 3) Submit and validate the result against the row's "expected" value
 */

// Generated by GitHub Copilot - Nov-23-2026
import path from 'path';
import { test, expect } from '../../fixtures/pageFixtures';
import { DataProvider } from '../../utils/DataReader';

type LoginData = {
    testName: string;
    email: string;
    password: string;
    expected: 'success' | 'failure';
};

const jsonPath = path.join(__dirname, '../../testdata/opencart_logindata.json');
const loginData: LoginData[] = DataProvider.readJson(jsonPath);

loginData.forEach((data, index) => {
    // Index keeps titles unique because several rows share the same testName.
    test(`${index + 1}) ${data.testName} - data driven login test @master @datadriven @web`, async ({ homePage, loginPage, myAccountPage }) => {
        const email = data.email.trim();
        const password = data.password.trim();

        await test.step('1) Navigate to the login page', async () => {
            await homePage.clickMyAccount();
            await homePage.clickLogin();
            expect(await loginPage.isLoginPageExists()).toBeTruthy();
        });

        await test.step('2) Enter the credentials and submit', async () => {
            await loginPage.login(email, password);
        });

        await test.step(`3) Verify the login result is "${data.expected}"`, async () => {
            if (data.expected === 'success') {
                expect(await myAccountPage.isMyAccountPageExists()).toBeTruthy();
            } else {
                // Blank email/password produce the same server-side warning as wrong credentials.
                const errorMessage = await loginPage.getLoginErrorMessage();
                expect(errorMessage).toContain('Warning: No match for E-Mail Address and/or Password.');
                expect(await loginPage.isLoginPageExists()).toBeTruthy();
            }
        });

        console.log(`✅ ✔️ ${data.testName} (row ${index + 1}) completed as expected!`);
    });
});
